"use client";

import { HEADING_TAGS, headingBelow, type HeadingLevelOption } from "../lib/heading";
import { isValidElement, useId, useRef, type ReactNode } from "react";
import { motion, useInView, type Variants } from "motion/react";

import { cn } from "../lib/cn";
import { duration, ease, spring } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { GlassCard } from "../glass-card/glass-card";

import { VisibleContext } from "./bento-grid/context";
import {
  type BentoChartLabels,
  BentoChartDemo,
  type BentoToastLabels,
  BentoToastDemo,
  type BentoOtpLabels,
  BentoOtpDemo,
  type BentoSwitchLabels,
  BentoSwitchDemo,
  type BentoAvatarLabels,
  BentoAvatarDemo,
} from "./bento-grid/demos";
import { ChartIcon, BellIcon, KeyIcon, LayersIcon, UsersIcon, ArrowRightIcon } from "./bento-grid/icons";

export { useBentoCellVisible } from "./bento-grid/context";
export {
  type BentoChartPeriod,
  type BentoChartLabels,
  defaultBentoChartLabels,
  type BentoChartDemoProps,
  BentoChartDemo,
  type BentoToast,
  defaultBentoToastLabels,
  type BentoToastLabels,
  type BentoToastDemoProps,
  BentoToastDemo,
  defaultBentoOtpLabels,
  type BentoOtpLabels,
  type BentoOtpDemoProps,
  BentoOtpDemo,
  defaultBentoSwitchLabels,
  type BentoSwitchLabels,
  type BentoSwitchDemoProps,
  BentoSwitchDemo,
  defaultBentoAvatarLabels,
  type BentoAvatarLabels,
  type BentoAvatarDemoProps,
  BentoAvatarDemo,
} from "./bento-grid/demos";

/**
 * Bento grid: an asymmetric grid of feature cells, each with a live mini-demo built from real
 * SheenUI components (sparkline, toast stack, OTP input, switches, avatar group).
 *
 *   <FeatureBento />                       // the ready-made block
 *
 *   <BentoGrid>                            // or compose your own
 *     <BentoCell colSpan={2} title="Analytics" visual={<BentoChartDemo />} />
 *     <BentoCell rowSpan={2} title="Notifications" visual={<BentoToastDemo />} />
 *   </BentoGrid>
 *
 * Lazy: a cell's visual mounts the first time the cell scrolls into view, so its entrance
 * animations play when they can be seen and nothing runs for cells nobody has reached.
 * Looping demos also pause while their cell is off screen (useBentoCellVisible).
 *
 * Motion: cells rise in one after another (the glass cell itself moves, never a wrapper
 * around glass). Reduced motion: cells only fade, demos skip their movement.
 *
 * Layout follows the grid's own width (container queries): 1 column, 2 from 36rem, 3 from 56rem.
 * Spans collapse on the way down, so the grid never overflows.
 */

/* ---------- Grid ---------- */

/** Props of `BentoGrid`. */
export type BentoGridProps = {
  /** Holds the cells (`ReactNode`, required): usually `BentoCell`s. */
  children: ReactNode;
  /** Classes for the outer element (the size container). */
  className?: string;
  /** Classes for the grid itself (gap, row height...). */
  gridClassName?: string;
};

/**
 * Props (see `BentoGridProps`): `children` (required), `className` (the size container) and
 * `gridClassName` (the grid itself: gap, row height). The grid follows its own width: 1 column, 2 from
 * 36rem, 3 from 56rem; cell spans shrink on the way down so it never overflows.
 * Keyboard and accessibility: a plain layout `<div>` with no semantics; cells carry their own headings.
 * Glass and motion: it adds no glass; each `BentoCell` is one glass card and rises in with a stagger.
 *
 * @example
 * ```tsx
 * import { BentoCell, BentoGrid } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <BentoGrid>
 *       <BentoCell title="Fast" description="60 fps with heavy graphics." colSpan={2} />
 *       <BentoCell title="Accessible" description="WCAG AA, keyboard first." />
 *     </BentoGrid>
 *   );
 * }
 * ```
 *
 * @see /blocks/bento-grid
 */
export function BentoGrid({ children, className, gridClassName }: BentoGridProps) {
  return (
    <div data-slot="bento-grid" className={cn("@container w-full min-w-0", className)}>
      <div
        className={cn(
          "grid grid-flow-row-dense auto-rows-[minmax(15rem,auto)] grid-cols-1 gap-4 @xl:grid-cols-2 @4xl:grid-cols-3 @4xl:gap-5",
          gridClassName,
        )}
      >
        {children}
      </div>
    </div>
  );
}

const colSpans = { 1: "", 2: "@xl:col-span-2", 3: "@xl:col-span-2 @4xl:col-span-3" } as const;
const rowSpans = { 1: "", 2: "@xl:row-span-2" } as const;

/** Props of `BentoCell`. */
export type BentoCellProps = {
  /** Sets the cell's heading (`ReactNode`, required). */
  title: ReactNode;
  /** Shows the text under the heading (`ReactNode`). */
  description?: ReactNode;
  /** Shows a small icon before the title. */
  icon?: ReactNode;
  /** Live preview or artwork. Mounted the first time the cell scrolls into view. */
  visual?: ReactNode;
  /** Columns spanned on the widest grid (3 columns); spans shrink with the grid. */
  colSpan?: 1 | 2 | 3;
  /** Sets how many rows the cell spans from 2 columns up. */
  rowSpan?: 1 | 2;
  /** "horizontal" puts the text beside the visual once the cell is wide enough. */
  orientation?: "vertical" | "horizontal";
  /** Adds a "learn more" link under the description. */
  href?: string;
  /** Text of the link (`string`, default "Learn more"). */
  cta?: string;
  /** Sets the position in the grid: staggers the entrance. */
  index?: number;
  /** Heading level of the title (1 to 6, default 3), or `"none"` for a paragraph with no heading role (for an example). */
  headingLevel?: HeadingLevelOption;
  /** Adds extra classes to the glass card (`string`). */
  className?: string;
  /** Adds extra classes to the visual area. */
  visualClassName?: string;
};

const MotionGlassCard = motion.create(GlassCard);

/* A cell's visual mounts lazily, so its box is reserved up front: the built-in demos are
   measured once (rem, so it follows the text size) and the cell is already its final height when
   the visual arrives, which keeps the page from shifting while it scrolls. */
const visualReserve = new Map<unknown, string>([
  [BentoChartDemo, "min-h-[15.9rem] @xl:min-h-52"],
  [BentoToastDemo, "min-h-[19.3rem]"],
  [BentoOtpDemo, "min-h-[16.9rem]"],
  [BentoSwitchDemo, "min-h-[16.9rem]"],
  [BentoAvatarDemo, "min-h-48"],
]);

/* The cell rises on a spring; its opacity only blinks in (duration.fast), so the glass controls
   inside it (toasts, OTP slots, pills) are never seen half-faded over the cell. */
const cellVariants: Variants = {
  hidden: { opacity: 0, y: 24 },
  visible: (index: number) => {
    const delay = Math.min(index, 6) * 0.08;
    return {
      opacity: 1,
      y: 0,
      transition: { y: { ...spring.gentle, delay }, opacity: { duration: duration.fast, ease: ease.out, delay } },
    };
  },
};
const cellVariantsReduced: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { duration: duration.base } },
};

/**
 * Use it inside a `BentoGrid`. Props (see `BentoCellProps`): `title` (required), `description`, `icon`,
 * `visual` (mounted the first time the cell scrolls into view), `colSpan` (`1`), `rowSpan` (`1`),
 * `orientation` (`"vertical"`), `href` and `cta`, `index` (`0`, staggers the entrance), `headingLevel`
 * (`"h3"`), `className`, `visualClassName`.
 * Keyboard: the optional link is the only tab stop the cell adds. Accessibility: a heading plus text;
 * the visual is lazy, so cells nobody reached cost nothing, and decorative visuals should be `aria-hidden`.
 * Glass and motion: one glass card that rises in (the card itself moves, never a wrapper); reduced
 * motion only fades.
 *
 * @example
 * ```tsx
 * import { BentoCell, BentoChartDemo } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <BentoCell title="Analytics" description="Charts that tween." colSpan={2} visual={<BentoChartDemo />} href="/charts" />
 *   );
 * }
 * ```
 *
 * @see /blocks/bento-grid
 */
export function BentoCell({
  title,
  description,
  icon,
  visual,
  colSpan = 1,
  rowSpan = 1,
  orientation = "vertical",
  href,
  cta = "Learn more",
  index = 0,
  headingLevel = 3,
  className,
  visualClassName,
}: BentoCellProps) {
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const reduced = useSheenReducedMotion();
  const ref = useRef<HTMLDivElement>(null);
  const titleId = useId();
  // Any part of the cell in view (minus a strip at the bottom edge): a fraction of a tall cell
  // could be out of reach on a short landscape screen.
  const seen = useInView(ref, { once: true, margin: "0px 0px -10% 0px" });
  const visible = useInView(ref, { amount: 0 });
  const horizontal = orientation === "horizontal";

  return (
    <MotionGlassCard
      ref={ref}
      level={2}
      role="group"
      aria-labelledby={titleId}
      custom={index}
      variants={reduced ? cellVariantsReduced : cellVariants}
      initial="hidden"
      animate={seen ? "visible" : "hidden"}
      className={cn(
        "group/bento relative flex min-w-0 flex-col overflow-hidden rounded-sheen-xl",
        horizontal && "@4xl:flex-row",
        colSpans[colSpan],
        rowSpans[rowSpan],
        className,
      )}
    >
      {/* Soft accent wash in the corner: decorative, and it never sits behind text. */}
      <span
        aria-hidden
        className="pointer-events-none absolute -top-24 -end-24 -z-10 size-64 rounded-full opacity-60 [background:radial-gradient(closest-side,var(--sheen-accent-soft),transparent)]"
      />
      {visual !== undefined && (
        <div
          className={cn(
            "relative flex min-h-44 min-w-0 flex-1 items-center justify-center p-5",
            isValidElement(visual) && visualReserve.get(visual.type),
            horizontal && "@4xl:order-2 @4xl:basis-3/5",
            visualClassName,
          )}
        >
          <VisibleContext value={visible}>{seen ? visual : null}</VisibleContext>
        </div>
      )}
      <div
        className={cn(
          "flex min-w-0 flex-col gap-1.5 p-5 pt-0",
          visual === undefined && "pt-5",
          horizontal && "@4xl:basis-2/5 @4xl:justify-center @4xl:p-8",
        )}
      >
        <Heading id={titleId} className="flex items-center gap-2 text-base font-semibold tracking-tight">
          {icon && (
            <span
              aria-hidden
              className="flex size-7 shrink-0 items-center justify-center rounded-sheen-sm bg-sheen-accent-soft text-sheen-accent [&_svg]:size-4"
            >
              {icon}
            </span>
          )}
          {title}
        </Heading>
        {description && <p className="text-sm text-pretty text-sheen-fg-muted">{description}</p>}
        {href && (
          <a
            href={href}
            className={cn(
              "group/link mt-1 inline-flex w-fit items-center gap-1 rounded-sheen-sm text-sm font-medium text-sheen-accent",
              "underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
              "relative any-pointer-coarse:after:absolute any-pointer-coarse:after:inset-x-0 any-pointer-coarse:after:top-1/2 any-pointer-coarse:after:h-11 any-pointer-coarse:after:-translate-y-1/2",
            )}
          >
            {cta}
            <ArrowRightIcon className="size-3.5 motion-ok:transition-transform motion-ok:duration-(--sheen-duration-base) motion-ok:ease-sheen-out motion-ok:group-hover/link:translate-x-0.5 rtl:motion-ok:group-hover/link:-translate-x-0.5" />
          </a>
        )}
      </div>
    </MotionGlassCard>
  );
}

/* =====================================================================
 * Ready-made block
 * ===================================================================== */

/** Every user-facing string of the `FeatureBento` showcase: the chart, toast, one-time-code, switch and avatar cells. */
export type FeatureBentoLabels = {
  chartTitle: string;
  chartDescription: string;
  toastTitle: string;
  toastDescription: string;
  otpTitle: string;
  otpDescription: string;
  switchTitle: string;
  switchDescription: string;
  avatarTitle: string;
  avatarDescription: string;
  chart: Partial<BentoChartLabels>;
  toast: Partial<BentoToastLabels>;
  otp: Partial<BentoOtpLabels>;
  switches: Partial<BentoSwitchLabels>;
  avatars: Partial<BentoAvatarLabels>;
};

/** Props of `FeatureBento`. */
export type FeatureBentoProps = {
  /** Section heading (`ReactNode`); leave out for none. */
  title?: ReactNode;
  /** Shows text under the heading (`ReactNode`). */
  description?: ReactNode;
  /** Heading level of `title`; cell titles are one level below (`2 | 3`, default 2). `"none"` renders them all as paragraphs with no heading role (for an example). */
  headingLevel?: HeadingLevelOption;
  /** Overrides for the built-in English strings (`Partial<FeatureBentoLabels>`). */
  labels?: Partial<FeatureBentoLabels>;
  /** Adds extra classes to the outer `<section>`. */
  className?: string;
};

/** The English strings of `FeatureBento`; pass `labels` to override any of them. */
export const defaultFeatureBentoLabels: FeatureBentoLabels = {
  chartTitle: "Charts that move with your data",
  chartDescription: "Sparklines draw themselves in and morph between periods. Every number counts up.",
  toastTitle: "Toasts that stack",
  toastDescription: "Newest in front, older ones peek out behind. Hover or focus to fan them out.",
  otpTitle: "One-time codes",
  otpDescription: "Auto-advance, paste a whole code, shake on a miss.",
  switchTitle: "Real glass, live",
  switchDescription: "Frost, tint and float the tile and watch the blur react.",
  avatarTitle: "Built for teams",
  avatarDescription:
    "Presence, avatars and invites, with springs that feel physical and stay still for anyone who asks for less motion.",
  chart: {},
  toast: {},
  otp: {},
  switches: {},
  avatars: {},
};

/**
 * The ready-made feature section: a heading and a `BentoGrid` of cells, each with a live mini-demo
 * (chart, toasts, OTP, switches, avatars). Props (see `FeatureBentoProps`): `title`, `description`,
 * `headingLevel` (`2`), `labels`, `className`.
 * Keyboard: Tab visits the controls inside each demo in reading order. Accessibility: a labelled
 * `<section>` when it has a title; one heading per cell. Glass and motion: one glass card per cell, which
 * rise in with a stagger; demos mount when they scroll into view and pause off screen; reduced motion
 * only fades.
 *
 * @example
 * ```tsx
 * import { FeatureBento } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <FeatureBento title="Everything you need" description="Glass, motion and accessibility, built in." />
 *   );
 * }
 * ```
 *
 * @see /blocks/bento-grid
 */
export function FeatureBento({ title, description, headingLevel = 2, labels, className }: FeatureBentoProps) {
  const L = { ...defaultFeatureBentoLabels, ...labels };
  const headingId = useId();
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const cellHeading = headingBelow(headingLevel);

  return (
    <section
      role="group"
      aria-labelledby={title ? headingId : undefined}
      data-slot="feature-bento"
      className={cn("flex w-full min-w-0 flex-col gap-8", className)}
    >
      {(Boolean(title) || description) && (
        <div className="flex flex-col items-center gap-3 text-center">
          {title && (
            <Heading id={headingId} className="text-3xl font-semibold tracking-tight text-balance sm:text-4xl">
              {title}
            </Heading>
          )}
          {description && <p className="max-w-xl text-base text-pretty text-sheen-fg-muted">{description}</p>}
        </div>
      )}
      <BentoGrid>
        <BentoCell
          index={0}
          colSpan={2}
          headingLevel={cellHeading}
          icon={<ChartIcon />}
          title={L.chartTitle}
          description={L.chartDescription}
          visual={<BentoChartDemo labels={L.chart} />}
        />
        <BentoCell
          index={1}
          rowSpan={2}
          headingLevel={cellHeading}
          icon={<BellIcon />}
          title={L.toastTitle}
          description={L.toastDescription}
          visual={<BentoToastDemo labels={L.toast} />}
        />
        <BentoCell
          index={2}
          headingLevel={cellHeading}
          icon={<KeyIcon />}
          title={L.otpTitle}
          description={L.otpDescription}
          visual={<BentoOtpDemo labels={L.otp} />}
        />
        <BentoCell
          index={3}
          headingLevel={cellHeading}
          icon={<LayersIcon />}
          title={L.switchTitle}
          description={L.switchDescription}
          visual={<BentoSwitchDemo labels={L.switches} />}
        />
        <BentoCell
          index={4}
          colSpan={3}
          orientation="horizontal"
          headingLevel={cellHeading}
          icon={<UsersIcon />}
          title={L.avatarTitle}
          description={L.avatarDescription}
          visual={<BentoAvatarDemo labels={L.avatars} />}
        />
      </BentoGrid>
    </section>
  );
}

"use client";

import { createContext, useContext } from "react";

/* ---------- Cell ---------- */

/** Tells a tile's demo whether the grid is on screen, so it can pause off-screen loops. @internal */
export const VisibleContext = createContext(true);

/**
 * True while the surrounding BentoCell is on screen: pause loops and timers when it's false.
 *
 * Returns `boolean` (`true` outside a cell). Call it inside a `BentoCell`'s `visual` to run intervals,
 * timers and loops only while the cell is on screen. Accessibility and keyboard: none of its own.
 * Motion: it is the off-screen pause rule of the motion playbook for bento demos.
 *
 * @example
 * ```tsx
 * import { useEffect, useState } from "react";
 * import { useBentoCellVisible } from "@sheenui/theme";
 *
 * function Ticker() {
 *   const visible = useBentoCellVisible();
 *   const [n, setN] = useState(0);
 *   useEffect(() => {
 *     if (!visible) return;
 *     const timer = window.setInterval(() => setN((v) => v + 1), 1000);
 *     return () => window.clearInterval(timer);
 *   }, [visible]);
 *   return <p>{n}</p>;
 * }
 * ```
 *
 * @see /blocks/bento-grid
 */
export function useBentoCellVisible() {
  return useContext(VisibleContext);
}

"use client";

import { useEffect, useEffectEvent, useId, useMemo, useRef, useState, type FocusEvent } from "react";
import { Radio } from "@base-ui/react/radio";
import { RadioGroup } from "@base-ui/react/radio-group";
import { AnimatePresence, animate, motion, useMotionValue, useTransform } from "motion/react";

import { cn } from "../../lib/cn";
import { duration, ease, spring } from "../../motion/tokens";
import { exitTransition } from "../../motion/presets";
import { useSheenReducedMotion } from "../../hooks/use-preferences";
import { Avatar, AvatarGroup } from "../../avatar/avatar";
import { Badge } from "../../badge/badge";
import { Button } from "../../button/button";
import { OtpInput, type OtpStatus } from "../../otp-input/otp-input";
import { Sparkline } from "../../charts/sparkline";
import { Switch } from "../../switch/switch";
import { useBentoCellVisible } from "./context";
import { BellIcon, TrendIcon, PlusIcon } from "./icons";

/* =====================================================================
 * Mini-demos
 * ===================================================================== */

/* ---------- Small radio pills (period pickers) ---------- */

/** A small segmented pill selector used inside the tile demos. @internal */
export function Pills<T extends string>({
  value,
  options,
  onChange,
  label,
  optionLabel,
  optionName,
}: {
  value: T;
  options: readonly T[];
  onChange: (value: T) => void;
  label: string;
  optionLabel: (value: T) => string;
  optionName: (value: T) => string;
}) {
  const reduced = useSheenReducedMotion();
  const pillId = useId();
  return (
    <RadioGroup
      value={value}
      onValueChange={(next) => onChange(next)}
      aria-label={label}
      className="glass-1 inline-flex items-center gap-0.5 rounded-sheen-full p-0.5"
    >
      {options.map((option) => (
        <Radio.Root
          key={option}
          value={option}
          aria-label={optionName(option)}
          className={cn(
            "relative isolate inline-flex h-7 min-w-9 cursor-pointer items-center justify-center rounded-sheen-full px-2.5 text-xs font-semibold tabular-nums select-none",
            "text-sheen-fg-muted transition-colors duration-(--sheen-duration-fast) hover:text-sheen-fg data-checked:text-sheen-fg",
            "touch-manipulation focus-visible:z-10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
            // 44px hit area on touch screens without changing the look.
            "any-pointer-coarse:after:absolute any-pointer-coarse:after:top-1/2 any-pointer-coarse:after:left-1/2 any-pointer-coarse:after:h-11 any-pointer-coarse:after:w-full any-pointer-coarse:after:min-w-11 any-pointer-coarse:after:-translate-1/2",
            "forced-colors:data-checked:underline forced-colors:data-checked:decoration-2 forced-colors:data-checked:underline-offset-4",
          )}
        >
          {value === option && (
            <motion.span
              aria-hidden
              layoutId={pillId}
              transition={reduced ? { duration: 0 } : spring.snappy}
              // The tabs' indicator token: the glass highlight's 0.34 white at night left the chosen label under 4.5:1.
              className="pointer-events-none absolute inset-0 -z-10 rounded-[inherit] bg-(--sheen-indicator) shadow-[inset_0_1px_0_var(--sheen-glass-highlight),0_0_0_1px_var(--sheen-glass-edge),0_1px_2px_var(--sheen-shadow-near)]"
            />
          )}
          <span aria-hidden>{optionLabel(option)}</span>
        </Radio.Root>
      ))}
    </RadioGroup>
  );
}

/* ---------- Chart ---------- */

/** One selectable period of the bento chart: its headline `total`, the `change` against the previous period in percent (8.2 = +8.2%) and the `values` plotted. */
export type BentoChartPeriod = { total: number; change: number; values: number[] };

/** Every user-facing string of the bento chart cell (metric name, period picker and period names). */
export type BentoChartLabels = {
  metric: string;
  /** Accessible name of the period picker. */
  period: string;
  /** Short text on a period pill ("7d" → "7D"). */
  periodShort: (key: string) => string;
  /** Spoken name of a period ("7d" → "Last 7 days"). */
  periodName: (key: string) => string;
  /** Change badge; receives the formatted percentage. */
  change: (direction: "up" | "down", amount: string) => string;
  /** Accessible name of the sparkline; receives the spoken change ("up 12.4%"). */
  trend: (metric: string, period: string, change: string) => string;
};

/** Props of `BentoChartDemo`. */
export type BentoChartDemoProps = {
  /** Figures per period (`Record<string, BentoChartPeriod>`, default: sample revenue); the keys become the period buttons. */
  data?: Record<string, BentoChartPeriod>;
  /** Sets the ISO 4217 currency (`string`, default `"USD"`). */
  currency?: string;
  /** Sets the BCP 47 locale (`string`, default `"en-US"`). */
  locale?: string;
  /** Overrides for the built-in English strings. */
  labels?: Partial<BentoChartLabels>;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** The English strings of the chart tile; pass `labels` to override any of them. */
export const defaultBentoChartLabels: BentoChartLabels = {
  metric: "Revenue",
  period: "Period",
  periodShort: (key) => key.toUpperCase(),
  periodName: (key) => {
    const match = /^(\d+)\s*([dwmy])$/i.exec(key);
    if (!match) return key;
    const n = Number(match[1]);
    const unit = { d: "day", w: "week", m: "month", y: "year" }[
      (match[2] ?? "d").toLowerCase() as "d" | "w" | "m" | "y"
    ];
    return `Last ${n} ${unit}${n === 1 ? "" : "s"}`;
  },
  change: (direction, amount) => `${direction === "up" ? "Up" : "Down"} ${amount}`,
  trend: (metric, period, change) => `${metric} trend, ${period.toLowerCase()}, ${change.toLowerCase()}`,
};

/** The default per-period series of the chart tile. @internal */
export const defaultChartData: Record<string, BentoChartPeriod> = {
  "7d": { total: 12480, change: 8.2, values: [1.1, 1.3, 1.2, 1.5, 1.4, 1.7, 1.6, 1.8, 1.7, 2.0, 1.9, 2.2] },
  "30d": { total: 48250, change: 12.4, values: [3.1, 3.4, 3.2, 3.8, 4.2, 4.0, 4.6, 4.4, 4.9, 5.3, 5.1, 5.8] },
  "90d": {
    total: 139900,
    change: -3.6,
    values: [14, 13.2, 13.8, 12.9, 12.4, 12.9, 12.1, 11.6, 12.2, 11.8, 11.1, 11.5],
  },
};

/**
 * A bento visual: a revenue total that counts up beside a sparkline, with period buttons that change
 * both. Props (see `BentoChartDemoProps`): `data`, `currency` (`"USD"`), `locale` (`"en-US"`), `labels`,
 * `className`. Keyboard: the period pills are a radio group; Tab enters it and the arrow keys change the period. Accessibility: the
 * total is read once as text, the sparkline has a text name. Motion: the count-up and the sparkline
 * draw-in run once; reduced motion shows the final values.
 *
 * @example
 * ```tsx
 * import { BentoChartDemo } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <BentoChartDemo currency="EUR" locale="de-DE" />
 *   );
 * }
 * ```
 *
 * @see /blocks/bento-grid
 */
export function BentoChartDemo({
  data = defaultChartData,
  currency = "USD",
  locale = "en-US",
  labels,
  className,
}: BentoChartDemoProps) {
  const L = { ...defaultBentoChartLabels, ...labels };
  const keys = Object.keys(data);
  const [period, setPeriod] = useState(keys[1] ?? keys[0] ?? "");
  const current = data[period];
  const reduced = useSheenReducedMotion();
  const { money, pct } = useMemo(
    () => ({
      money: new Intl.NumberFormat(locale, {
        style: "currency",
        currency,
        notation: "compact",
        maximumFractionDigits: 1,
      }),
      pct: new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 1 }),
    }),
    [locale, currency],
  );

  // Count to the new total whenever the period changes (straight to it with reduced motion).
  const total = useMotionValue(0);
  const text = useTransform(total, (n) => money.format(n));
  useEffect(() => {
    if (!current) return;
    if (reduced) {
      total.set(current.total);
      return;
    }
    const controls = animate(total, current.total, { duration: duration.slower * 1.4, ease: ease.out });
    return () => controls.stop();
  }, [current, reduced, total]);

  if (!current) return null;
  const up = current.change >= 0;
  const amount = pct.format(Math.abs(current.change) / 100);
  const changeText = L.change(up ? "up" : "down", amount);

  return (
    <div data-slot="bento-chart-demo" className={cn("flex w-full max-w-xl flex-col gap-4 self-stretch", className)}>
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="flex flex-col gap-1">
          <p className="text-xs font-medium text-sheen-fg-muted">{L.metric}</p>
          <p className="flex items-center gap-2.5">
            {/* The final figure sets the width from the start, so the count-up never changes
                where the header wraps (a wrap flip would jump the whole cell). */}
            <span aria-hidden className="inline-grid text-3xl font-semibold tracking-tight tabular-nums">
              <span className="invisible col-start-1 row-start-1">{money.format(current.total)}</span>
              <motion.span className="col-start-1 row-start-1">{text}</motion.span>
            </span>
            <span className="sr-only">{money.format(current.total)}</span>
            <Badge tone={up ? "success" : "danger"} className="h-5 gap-1 px-2 text-2xs font-semibold">
              <TrendIcon up={up} className="size-3" />
              {changeText}
            </Badge>
          </p>
        </div>
        <Pills
          value={period}
          options={keys}
          onChange={setPeriod}
          label={L.period}
          optionLabel={L.periodShort}
          optionName={L.periodName}
        />
      </div>
      <Sparkline values={current.values} height={96} aria-label={L.trend(L.metric, L.periodName(period), changeText)} />
    </div>
  );
}

/* ---------- Toast stack ---------- */

/** A notification in the bento toast stack: a tone (`success`, `info` or `error`), a title and a description. */
export type BentoToast = { tone: "success" | "info" | "danger"; title: string; description: string };

/** Every user-facing string of the bento toast cell (stack name and the send button). */
export type BentoToastLabels = {
  /** Accessible name of the stack. */
  region: string;
  send: string;
};

/** The English strings of the toast tile; pass `labels` to override any of them. */
export const defaultBentoToastLabels: BentoToastLabels = { region: "Sample notifications", send: "Send notification" };

/** Props of `BentoToastDemo`. */
export type BentoToastDemoProps = {
  /** Notifications to cycle through. The first three play on their own when the cell appears. */
  notifications?: BentoToast[];
  /** Overrides for the built-in English strings. */
  labels?: Partial<BentoToastLabels>;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** The default notifications of the toast-stack tile. @internal */
export const defaultToasts: BentoToast[] = [
  { tone: "success", title: "Deploy finished", description: "sheen-web is live on production." },
  { tone: "info", title: "New comment", description: "Maya replied to “Glass tokens”." },
  { tone: "success", title: "Payment received", description: "$249.00 from Northwind." },
  { tone: "danger", title: "Build failed", description: "2 type errors in pricing.tsx." },
  { tone: "info", title: "Invite accepted", description: "Leo joined the Design team." },
];

/** The colour and icon path of each toast tone. @internal */
export const toneIcon = {
  success: { color: "text-sheen-success-text", path: "M8 12.5l2.5 2.5L16 9.5" },
  info: { color: "text-sheen-accent", path: "M12 16v-4m0-4h.01" },
  danger: { color: "text-sheen-danger-text", path: "M12 8v4m0 4h.01" },
} as const;

/** The height of one stacked toast, in pixels. @internal */
export const TOAST_H = 64;
/** The gap between toasts when the stack is fanned out, in pixels. @internal */
export const TOAST_GAP = 8;
/** How far each toast behind the front one peeks out, in pixels. @internal */
export const TOAST_PEEK = 10;
/** The number of toasts visible in the collapsed stack. @internal */
export const STACK = 3;
/** The number of toasts that arrive during the intro animation. @internal */
export const INTRO_COUNT = 3;
/* The region is tall enough for the fanned-out stack; at rest the stack sits in its middle. */
/** The height of the toast stack when it is fanned out, in pixels. @internal */
export const STACK_FANNED = STACK * TOAST_H + (STACK - 1) * TOAST_GAP;
/** The vertical offset that centres the collapsed toast stack. @internal */
export const STACK_REST_Y = (STACK_FANNED - (TOAST_H + (STACK - 1) * TOAST_PEEK)) / 2;

/**
 * A bento visual: a stack of glass notifications that plays three on its own, spreads on hover or
 * focus, and has a button to send another. Props (see `BentoToastDemoProps`): `notifications`
 * (sample list, cycled), `labels`, `className`.
 * Keyboard: Tab reaches the send button; the stack expands while focus is inside it. Accessibility: the
 * stack is a focusable `group` named "Sample notifications" (not "Notifications", which is usually the app's own toast
 * region; a group, not a landmark) and new items are announced politely. Motion: items slide in; the loop pauses while the cell
 * is off screen; reduced motion adds items without movement.
 *
 * @example
 * ```tsx
 * import { BentoToastDemo } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <BentoToastDemo notifications={[{ tone: "success", title: "Deploy finished", description: "acme-web is live" }]} />
 *   );
 * }
 * ```
 *
 * @see /blocks/bento-grid
 */
export function BentoToastDemo({ notifications = defaultToasts, labels, className }: BentoToastDemoProps) {
  // Not "Notifications": that is usually the app's real toast region.
  const L = { ...defaultBentoToastLabels, ...labels };
  const reduced = useSheenReducedMotion();
  const visible = useBentoCellVisible();
  const [items, setItems] = useState<(BentoToast & { id: number })[]>([]);
  const [expanded, setExpanded] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const next = useRef(0);
  const pointer = useRef("");

  function push(announce: boolean) {
    if (notifications.length === 0) return;
    const toast = notifications[next.current % notifications.length];
    if (!toast) return;
    const id = next.current++;
    setItems((list) => [{ ...toast, id }, ...list].slice(0, STACK + 1));
    if (announce) setAnnouncement(`${toast.title}. ${toast.description}`);
  }

  // Three notifications arrive on their own (about 2.5 s in all), then the stack rests. Only
  // once: if the cell scrolls away mid-intro, the rest arrive when it is back; never again after.
  const introFired = useRef(0);
  // `push` only reads refs and props, so a new identity must not reset the timers: it is read when a timer fires.
  const pushIntro = useEffectEvent(() => push(false));
  useEffect(() => {
    const left = INTRO_COUNT - introFired.current;
    if (left <= 0 || !visible) return;
    const timers = Array.from({ length: left }, (_, i) =>
      window.setTimeout(
        () => {
          introFired.current++;
          pushIntro();
        },
        300 + i * 1000,
      ),
    );
    return () => timers.forEach((t) => window.clearTimeout(t));
  }, [visible]);

  function leave(event: FocusEvent<HTMLDivElement>) {
    if (!event.currentTarget.contains(event.relatedTarget)) setExpanded(false);
  }

  const shown = items.slice(0, STACK);

  return (
    <div data-slot="bento-toast-demo" className={cn("flex w-full max-w-80 flex-col items-center gap-4", className)}>
      {/* Hover or focus fans the stack out (a tap toggles it on touch screens). */}
      {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions -- a tap toggles the fanned stack on touch screens; keyboard users get the same result from focus (onFocus below), so no key handler is needed */}
      <div
        role="group"
        aria-label={L.region}
        // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- keyboard focus is what fans the stack out and reveals every notification
        tabIndex={0}
        onPointerEnter={(e) => e.pointerType === "mouse" && setExpanded(true)}
        onPointerLeave={(e) => e.pointerType === "mouse" && setExpanded(false)}
        onPointerDown={(e) => {
          pointer.current = e.pointerType;
        }}
        onClick={() => pointer.current !== "mouse" && setExpanded((open) => !open)}
        // Keyboard focus fans it out; a tap's focus is left to the click above.
        onFocus={(e) => e.target.matches(":focus-visible") && setExpanded(true)}
        onBlur={leave}
        className="relative w-full rounded-sheen-lg focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-sheen-focus"
        style={{ height: STACK_FANNED }}
      >
        <ol className="contents">
          <AnimatePresence initial={false}>
            {shown.map((toast, i) => {
              const front = i === 0;
              const y = expanded ? i * (TOAST_H + TOAST_GAP) : STACK_REST_Y + i * TOAST_PEEK;
              const scale = expanded || reduced ? 1 : 1 - i * 0.06;
              return (
                <motion.li
                  key={toast.id}
                  // The glass toast moves and fades itself (no wrapper around the glass).
                  className="glass-2 absolute inset-x-0 top-0 flex origin-top items-center gap-3 rounded-sheen-lg px-3.5 select-none"
                  style={{ height: TOAST_H, zIndex: STACK - i }}
                  initial={reduced ? { opacity: 0, y } : { opacity: 0, y: y - TOAST_H * 0.6, scale: 0.96 }}
                  animate={{ opacity: 1, y, scale }}
                  exit={
                    reduced
                      ? { opacity: 0, transition: exitTransition }
                      : { opacity: 0, scale: scale - 0.04, transition: exitTransition }
                  }
                  transition={reduced ? { duration: 0, opacity: { duration: duration.fast } } : spring.gentle}
                >
                  <motion.span
                    className="flex min-w-0 flex-1 items-center gap-3"
                    // Toasts behind the front one show only their edge, so their text fades out.
                    animate={{ opacity: front || expanded ? 1 : 0 }}
                    transition={{ duration: duration.fast }}
                  >
                    <svg
                      aria-hidden
                      viewBox="0 0 24 24"
                      className={cn("size-5 shrink-0", toneIcon[toast.tone].color)}
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <circle cx="12" cy="12" r="9" />
                      <path d={toneIcon[toast.tone].path} />
                    </svg>
                    <span className="flex min-w-0 flex-col">
                      <span className="truncate text-sm font-semibold">{toast.title}</span>
                      <span className="truncate text-xs text-sheen-fg-muted">{toast.description}</span>
                    </span>
                  </motion.span>
                </motion.li>
              );
            })}
          </AnimatePresence>
        </ol>
      </div>
      <Button variant="glass" size="sm" onClick={() => push(true)} leading={<BellIcon className="size-3.5" />}>
        {L.send}
      </Button>
      <p aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

