          variant="glass"
          size="sm"
          onClick={() => setCount((c) => (full ? start : c + 1))}
          leading={full ? undefined : <PlusIcon className="size-3.5" />}
        >
          {full ? L.reset : L.invite}
        </Button>
      </div>
    </div>
  );
}

